text:
calendar-dialog-subview-manager {
  display: block;
  overflow-y: auto;

  & > *:not([hidden]) {
    block-size: 100%;
    display: flex;
    flex-direction: column;
    gap: var(--calendar-dialog-gap);
  }

  #calendarDialogMainSubview {
    padding-block-end: var(--calendar-dialog-gap);
  }
}
